-- Replace the old owner policies: they allowed a caller to choose is_admin_reply.
DO $$ DECLARE p record;
BEGIN
  FOR p IN SELECT tablename,policyname FROM pg_policies
    WHERE schemaname='public' AND tablename IN ('support_tickets','ticket_replies')
  LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,p.tablename); END LOOP;
END $$;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ticket_replies ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.support_tickets,public.ticket_replies TO authenticated;
REVOKE ALL ON public.support_tickets,public.ticket_replies FROM anon,PUBLIC;
REVOKE INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER,REFERENCES ON public.support_tickets,public.ticket_replies FROM authenticated;
CREATE POLICY ticket_owner_read ON public.support_tickets FOR SELECT TO authenticated
USING(user_id=auth.uid() OR public.app_admin_allowed('manage_support'));
CREATE POLICY ticket_owner_create ON public.support_tickets FOR INSERT TO authenticated
WITH CHECK(user_id=auth.uid() AND status='pending' AND priority='normal'
  AND admin_notes IS NULL AND resolved_at IS NULL);
CREATE POLICY reply_participant_read ON public.ticket_replies FOR SELECT TO authenticated
USING(EXISTS(SELECT 1 FROM public.support_tickets t WHERE t.id=ticket_id
  AND (t.user_id=auth.uid() OR public.app_admin_allowed('manage_support'))));
CREATE POLICY reply_owner_create ON public.ticket_replies FOR INSERT TO authenticated
WITH CHECK(user_id=auth.uid() AND is_admin_reply IS FALSE AND EXISTS(
  SELECT 1 FROM public.support_tickets t WHERE t.id=ticket_id AND t.user_id=auth.uid()));

CREATE OR REPLACE FUNCTION public.send_admin_chat_message(p_message text,p_request_id uuid,p_ticket_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); ticket public.support_tickets%ROWTYPE;
  previous public.support_message_requests%ROWTYPE; result_reply uuid; admin_reply boolean;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Silakan login kembali' USING ERRCODE='42501'; END IF;
  IF p_request_id IS NULL OR nullif(btrim(p_message),'') IS NULL OR length(p_message)>5000 THEN
    RAISE EXCEPTION 'Pesan wajib diisi, maksimal 5000 karakter'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(actor::text,0));
  SELECT * INTO previous FROM public.support_message_requests WHERE id=p_request_id;
  IF FOUND THEN
    IF previous.user_id<>actor OR previous.body<>btrim(p_message)
      OR (p_ticket_id IS NOT NULL AND previous.ticket_id<>p_ticket_id) THEN
      RAISE EXCEPTION 'Referensi pengiriman sudah digunakan'; END IF;
    RETURN jsonb_build_object('ticket_id',previous.ticket_id,'reply_id',previous.reply_id);
  END IF;
  IF p_ticket_id IS NOT NULL THEN
    SELECT * INTO ticket FROM public.support_tickets WHERE id=p_ticket_id FOR UPDATE;
    IF NOT FOUND OR (ticket.user_id<>actor AND NOT public.app_admin_allowed('manage_support')) THEN
      RAISE EXCEPTION 'Percakapan tidak tersedia' USING ERRCODE='42501'; END IF;
  ELSE
    SELECT t.* INTO ticket FROM public.admin_conversations c JOIN public.support_tickets t ON t.id=c.ticket_id
      WHERE c.user_id=actor FOR UPDATE OF t;
    IF NOT FOUND THEN
      SELECT * INTO ticket FROM public.support_tickets WHERE user_id=actor ORDER BY created_at DESC,id DESC LIMIT 1 FOR UPDATE;
      IF FOUND THEN INSERT INTO public.admin_conversations VALUES(actor,ticket.id); END IF;
    END IF;
  END IF;
  IF ticket.id IS NULL THEN
    INSERT INTO public.support_tickets(user_id,subject,message,status,priority)
    VALUES(actor,'Chat dengan Admin',btrim(p_message),'pending','normal') RETURNING * INTO ticket;
    INSERT INTO public.admin_conversations VALUES(actor,ticket.id);
  ELSE
    admin_reply:=ticket.user_id<>actor;
    INSERT INTO public.ticket_replies(ticket_id,user_id,message,is_admin_reply)
    VALUES(ticket.id,actor,btrim(p_message),admin_reply) RETURNING id INTO result_reply;
    UPDATE public.support_tickets SET status=CASE WHEN admin_reply THEN 'in_progress' ELSE 'pending' END,
      resolved_at=NULL,updated_at=now() WHERE id=ticket.id;
  END IF;
  INSERT INTO public.support_message_requests(id,user_id,ticket_id,reply_id,body)
    VALUES(p_request_id,actor,ticket.id,result_reply,btrim(p_message));
  RETURN jsonb_build_object('ticket_id',ticket.id,'reply_id',result_reply);
END $$;

CREATE OR REPLACE FUNCTION public.get_admin_chat_summary()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); ticket public.support_tickets%ROWTYPE; last_reply public.ticket_replies%ROWTYPE; unread bigint;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Silakan login kembali' USING ERRCODE='42501'; END IF;
  SELECT t.* INTO ticket FROM public.admin_conversations c JOIN public.support_tickets t ON t.id=c.ticket_id WHERE c.user_id=actor;
  IF NOT FOUND THEN SELECT * INTO ticket FROM public.support_tickets WHERE user_id=actor ORDER BY created_at DESC,id DESC LIMIT 1; END IF;
  IF ticket.id IS NULL THEN RETURN jsonb_build_object('ticket_id',NULL,'unread',0); END IF;
  SELECT * INTO last_reply FROM public.ticket_replies WHERE ticket_id=ticket.id ORDER BY created_at DESC,id DESC LIMIT 1;
  SELECT count(*) INTO unread FROM public.ticket_replies r WHERE r.ticket_id=ticket.id AND r.is_admin_reply
    AND r.created_at>coalesce((SELECT read_at FROM public.ticket_read_states WHERE ticket_id=ticket.id AND user_id=actor),'-infinity'::timestamptz);
  RETURN jsonb_build_object('ticket_id',ticket.id,'last_message',coalesce(last_reply.message,ticket.message),
    'last_at',coalesce(last_reply.created_at,ticket.created_at),'unread',unread,'status',ticket.status);
END $$;

CREATE OR REPLACE FUNCTION public.get_support_thread(p_ticket_id uuid,p_offset integer DEFAULT 0)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE ticket public.support_tickets%ROWTYPE; messages jsonb; total bigint;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Silakan login kembali' USING ERRCODE='42501'; END IF;
  SELECT * INTO ticket FROM public.support_tickets WHERE id=p_ticket_id;
  IF NOT FOUND OR (ticket.user_id<>auth.uid() AND NOT public.app_admin_allowed('manage_support')) THEN
    RAISE EXCEPTION 'Percakapan tidak tersedia' USING ERRCODE='42501'; END IF;
  SELECT count(*) INTO total FROM public.ticket_replies WHERE ticket_id=ticket.id;
  SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.created_at,r.id),'[]'::jsonb) INTO messages
  FROM (SELECT id,user_id,message,is_admin_reply,created_at FROM public.ticket_replies
    WHERE ticket_id=ticket.id ORDER BY created_at DESC,id DESC LIMIT 50 OFFSET greatest(0,coalesce(p_offset,0))) r;
  RETURN jsonb_build_object('ticket',jsonb_build_object('id',ticket.id,'subject',ticket.subject,
    'message',ticket.message,'created_at',ticket.created_at,'status',ticket.status,'user_id',ticket.user_id),
    'messages',messages,'has_more',total>greatest(0,coalesce(p_offset,0))+50);
END $$;

CREATE OR REPLACE FUNCTION public.mark_support_thread_read(p_ticket_id uuid,p_through timestamptz)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.support_tickets WHERE id=p_ticket_id
    AND (user_id=auth.uid() OR public.app_admin_allowed('manage_support'))) THEN
    RAISE EXCEPTION 'Percakapan tidak tersedia' USING ERRCODE='42501'; END IF;
  IF p_through IS NULL OR p_through>now() THEN RAISE EXCEPTION 'Waktu baca tidak valid'; END IF;
  INSERT INTO public.ticket_read_states VALUES(p_ticket_id,auth.uid(),p_through)
    ON CONFLICT(ticket_id,user_id) DO UPDATE SET read_at=greatest(public.ticket_read_states.read_at,excluded.read_at);
  IF to_regclass('public.notification_recipients') IS NOT NULL THEN
    UPDATE public.notification_recipients r SET read_at=now() FROM public.notification_events e
      WHERE e.id=r.event_id AND e.category='support' AND e.entity_id=p_ticket_id
        AND r.user_id=auth.uid() AND r.read_at IS NULL AND r.created_at<=p_through;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.admin_update_ticket(p_ticket_id uuid,p_values jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE ticket public.support_tickets%ROWTYPE; next_status text;
BEGIN
  IF NOT public.app_admin_allowed('manage_support') THEN RAISE EXCEPTION 'Tidak memiliki izin mengelola bantuan' USING ERRCODE='42501'; END IF;
  IF jsonb_typeof(p_values)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_values) k WHERE k NOT IN ('status','priority','admin_notes')) THEN
    RAISE EXCEPTION 'Perubahan tiket tidak valid'; END IF;
  IF p_values ? 'status' AND coalesce(p_values->>'status','') NOT IN ('pending','open','in_progress','resolved','closed') THEN RAISE EXCEPTION 'Status tidak valid'; END IF;
  IF p_values ? 'priority' AND coalesce(p_values->>'priority','') NOT IN ('low','normal','high','urgent') THEN RAISE EXCEPTION 'Prioritas tidak valid'; END IF;
  SELECT * INTO ticket FROM public.support_tickets WHERE id=p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tiket tidak ditemukan'; END IF;
  next_status:=coalesce(p_values->>'status',ticket.status);
  UPDATE public.support_tickets SET status=next_status,priority=coalesce(p_values->>'priority',priority),updated_at=now(),
    resolved_at=CASE WHEN next_status IN ('resolved','closed') THEN coalesce(resolved_at,now()) ELSE NULL END WHERE id=p_ticket_id RETURNING * INTO ticket;
  IF p_values ? 'admin_notes' THEN
    IF length(p_values->>'admin_notes')>20000 THEN RAISE EXCEPTION 'Catatan terlalu panjang'; END IF;
    INSERT INTO public.ticket_internal_notes VALUES(p_ticket_id,coalesce(p_values->>'admin_notes',''),now(),auth.uid())
      ON CONFLICT(ticket_id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at,updated_by=excluded.updated_by;
  END IF;
  RETURN jsonb_build_object('id',ticket.id,'status',ticket.status,'priority',ticket.priority,'resolved_at',ticket.resolved_at,'updated_at',ticket.updated_at);
END $$;

CREATE OR REPLACE FUNCTION public.set_my_ranking_consent(p_enabled boolean)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF auth.uid() IS NULL OR p_enabled IS NULL THEN RAISE EXCEPTION 'Authentication and choice required' USING ERRCODE='42501'; END IF;
  UPDATE public.alumni SET consents=jsonb_set(CASE WHEN jsonb_typeof(consents)='object' THEN consents ELSE '{}'::jsonb END,
    '{ranking}',to_jsonb(p_enabled),true) WHERE user_id=auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'Alumni profile required'; END IF;
  RETURN p_enabled;
END $$;

DO $$ DECLARE f regprocedure;
BEGIN
  FOREACH f IN ARRAY ARRAY[
    'public.send_admin_chat_message(text,uuid,uuid)'::regprocedure,'public.get_admin_chat_summary()'::regprocedure,
    'public.get_support_thread(uuid,integer)'::regprocedure,'public.mark_support_thread_read(uuid,timestamptz)'::regprocedure,
    'public.admin_update_ticket(uuid,jsonb)'::regprocedure,'public.set_my_ranking_consent(boolean)'::regprocedure
  ] LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',f);
  END LOOP;
END $$;

DO $$ DECLARE target text;
BEGIN
  IF EXISTS(SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime') THEN
    FOREACH target IN ARRAY ARRAY['support_tickets','ticket_replies'] LOOP
      IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=target) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',target);
      END IF;
    END LOOP;
  END IF;
END $$;


-- Source: 009_admin_content_operations.sql
-- SHA256: 037239416eda7ce207f427b2eb143bcc0cd09b45a559c4155b3141ccec470b47
CREATE TABLE public.admin_action_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor uuid NOT NULL REFERENCES auth.users(id),
  entity_table text NOT NULL,
  entity_id uuid NOT NULL,
  action text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.admin_action_log ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.admin_action_log FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.admin_action_log TO authenticated;
CREATE POLICY admin_action_read ON public.admin_action_log FOR SELECT TO authenticated
USING(public.app_admin_allowed('moderate_content'));

DO $$ DECLARE target text;
BEGIN
  FOREACH target IN ARRAY ARRAY['berita','kegiatan','komunitas','donasi','tantangan','messages'] LOOP
    EXECUTE format('ALTER TABLE public.%I ADD COLUMN archived_at timestamptz',target);
    -- Restrictive policies also protect old clients that do not filter archived_at.
    EXECUTE format('CREATE POLICY app_hide_archived ON public.%I AS RESTRICTIVE FOR SELECT TO anon,authenticated USING (archived_at IS NULL)',target);
    IF NOT (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid=format('public.%I',target)::regclass) THEN
      IF target='tantangan' THEN
        ALTER TABLE public.tantangan ENABLE ROW LEVEL SECURITY;
        CREATE POLICY app_challenge_read ON public.tantangan FOR SELECT TO authenticated USING(true);
        CREATE POLICY app_challenge_public_read ON public.tantangan FOR SELECT TO anon USING(is_active IS TRUE);
        CREATE POLICY app_challenge_manage ON public.tantangan FOR ALL TO authenticated
          USING(public.app_admin_allowed('manage_kegiatan')) WITH CHECK(public.app_admin_allowed('manage_kegiatan'));
      ELSE
        RAISE EXCEPTION 'Review RLS before archiving table %',target;
      END IF;
    END IF;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.admin_archive_content(p_table text,p_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE needed text; found_id uuid;
BEGIN
  needed:=CASE p_table WHEN 'berita' THEN 'manage_berita' WHEN 'kegiatan' THEN 'manage_kegiatan'
    WHEN 'komunitas' THEN 'manage_komunitas' WHEN 'donasi' THEN 'manage_donasi'
    WHEN 'tantangan' THEN 'manage_kegiatan' WHEN 'messages' THEN 'moderate_content' END;
  IF needed IS NULL OR NOT public.app_admin_allowed(needed) THEN
    RAISE EXCEPTION 'Tidak memiliki izin mengarsipkan konten' USING ERRCODE='42501'; END IF;
  IF p_table='donasi' AND EXISTS(SELECT 1 FROM public.transactions WHERE donation_id=p_id AND status IN ('pending','authorize')) THEN
    RAISE EXCEPTION 'Masih ada pembayaran berjalan. Selesaikan pemeriksaan transaksi terlebih dahulu.'; END IF;
  EXECUTE format('UPDATE public.%I SET archived_at=now() WHERE id=$1 AND archived_at IS NULL RETURNING id',p_table) INTO found_id USING p_id;
  IF found_id IS NULL THEN RAISE EXCEPTION 'Konten tidak ditemukan atau sudah diarsipkan'; END IF;
  IF p_table='tantangan' THEN UPDATE public.tantangan SET is_active=false WHERE id=p_id; END IF;
  IF p_table='kegiatan' THEN UPDATE public.tantangan SET is_active=false WHERE kegiatan_id=p_id; END IF;
  INSERT INTO public.admin_action_log(actor,entity_table,entity_id,action) VALUES(auth.uid(),p_table,p_id,'archive');
  RETURN jsonb_build_object('id',found_id,'archived',true);
END $$;
REVOKE ALL ON FUNCTION public.admin_archive_content(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_archive_content(text,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_admin_product_overview()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE month_start timestamptz:=date_trunc('month',now() AT TIME ZONE 'Asia/Jakarta') AT TIME ZONE 'Asia/Jakarta';
BEGIN
  IF NOT public.app_admin_allowed('view_analytics') THEN RAISE EXCEPTION 'Tidak memiliki izin melihat statistik' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object(
    'alumni',jsonb_build_object('total',(SELECT count(*) FROM public.alumni),
      'verified',(SELECT count(*) FROM public.alumni_verification)),
    'kegiatan',jsonb_build_object('total',(SELECT count(*) FROM public.kegiatan WHERE archived_at IS NULL),
      'upcoming',(SELECT count(*) FROM public.kegiatan WHERE archived_at IS NULL AND kegiatan_date>=(now() AT TIME ZONE 'Asia/Jakarta')::date)),
    'donasi',jsonb_build_object('total',(SELECT count(*) FROM public.donasi WHERE archived_at IS NULL),
      'totalAmount',(SELECT coalesce(sum(target_amount),0) FROM public.donasi WHERE archived_at IS NULL)),
    'berita',jsonb_build_object('total',(SELECT count(*) FROM public.berita WHERE archived_at IS NULL),
      'thisMonth',(SELECT count(*) FROM public.berita WHERE archived_at IS NULL AND created_at>=month_start)),
    'komunitas',jsonb_build_object('total',(SELECT count(*) FROM public.komunitas WHERE archived_at IS NULL),
      'verified',(SELECT count(DISTINCT v.komunitas_id) FROM public.komunitas_verification v JOIN public.komunitas k ON k.id=v.komunitas_id WHERE k.archived_at IS NULL))
  );
END $$;
REVOKE ALL ON FUNCTION public.get_admin_product_overview() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_admin_product_overview() TO authenticated;


-- Source: 010_admin_role_operations.sql
-- SHA256: 5f047f28abef562648c8799e21573e5d94bd5c40b3f038c7d42485bae0894d79
CREATE OR REPLACE FUNCTION public.admin_save_role(p_id bigint,p_name text,p_description text,p_permissions bigint[])
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result bigint; permission_id bigint;
BEGIN
  IF NOT public.app_admin_allowed('manage_roles') THEN RAISE EXCEPTION 'Tidak memiliki izin mengelola role' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('satu-admin-roles',0));
  IF nullif(btrim(p_name),'') IS NULL OR length(p_name)>100 THEN RAISE EXCEPTION 'Nama role tidak valid'; END IF;
  IF p_permissions IS NULL OR array_position(p_permissions,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Pilihan izin tidak valid'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(p_permissions) i WHERE NOT EXISTS(SELECT 1 FROM public.permissions p WHERE p.id=i)) THEN RAISE EXCEPTION 'Salah satu izin tidak ditemukan'; END IF;
  IF p_id IS NULL THEN
    INSERT INTO public.roles(name,description) VALUES(btrim(p_name),p_description) RETURNING id INTO result;
  ELSE
    UPDATE public.roles SET name=btrim(p_name),description=p_description WHERE id=p_id RETURNING id INTO result;
    IF NOT FOUND THEN RAISE EXCEPTION 'Role tidak ditemukan'; END IF;
    DELETE FROM public.role_permissions WHERE role_id=p_id;
  END IF;
  FOR permission_id IN SELECT DISTINCT unnest(p_permissions) LOOP
    INSERT INTO public.role_permissions(role_id,permission_id) VALUES(result,permission_id);
  END LOOP;
  IF NOT public.app_admin_allowed('manage_roles') THEN RAISE EXCEPTION 'Perubahan ini akan menghilangkan akses pengelolaan Anda sendiri'; END IF;
  RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.admin_delete_role(p_id bigint)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result bigint;
BEGIN
  IF NOT public.app_admin_allowed('manage_roles') THEN RAISE EXCEPTION 'Tidak memiliki izin mengelola role' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('satu-admin-roles',0));
  IF EXISTS(SELECT 1 FROM public.admin_roles WHERE role_id=p_id) THEN RAISE EXCEPTION 'Role masih digunakan oleh admin'; END IF;
  DELETE FROM public.role_permissions WHERE role_id=p_id;
  DELETE FROM public.roles WHERE id=p_id RETURNING id INTO result;
  IF NOT FOUND THEN RAISE EXCEPTION 'Role tidak ditemukan'; END IF;
  RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.admin_set_membership(p_user_id uuid,p_role_id bigint,p_enabled boolean)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF NOT public.app_admin_allowed('manage_roles') THEN RAISE EXCEPTION 'Tidak memiliki izin mengelola admin' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('satu-admin-roles',0));
  IF p_enabled IS NULL OR NOT EXISTS(SELECT 1 FROM public.roles WHERE id=p_role_id) OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_user_id) THEN RAISE EXCEPTION 'Akun atau role tidak valid'; END IF;
  IF p_enabled THEN
    INSERT INTO public.admin_roles(user_id,role_id) VALUES(p_user_id,p_role_id) ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM public.admin_roles WHERE user_id=p_user_id AND role_id=p_role_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Penugasan role tidak ditemukan'; END IF;
    IF NOT public.app_admin_allowed('manage_roles') THEN RAISE EXCEPTION 'Tidak dapat menghapus akses pengelolaan Anda sendiri'; END IF;
  END IF;
  RETURN p_enabled;
END $$;

CREATE OR REPLACE FUNCTION public.admin_save_permission(p_id bigint,p_name text,p_description text,p_delete boolean DEFAULT false)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result bigint;
BEGIN
  IF NOT public.app_admin_allowed('manage_roles') THEN RAISE EXCEPTION 'Tidak memiliki izin mengelola permission' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('satu-admin-roles',0));
  IF p_delete THEN
    IF EXISTS(SELECT 1 FROM public.role_permissions WHERE permission_id=p_id) THEN RAISE EXCEPTION 'Permission masih digunakan oleh role'; END IF;
    DELETE FROM public.permissions WHERE id=p_id RETURNING id INTO result;
    IF NOT FOUND THEN RAISE EXCEPTION 'Permission tidak ditemukan'; END IF;
  ELSE
    IF p_id IS NOT NULL OR p_name IS NULL OR length(p_name)<3 OR length(p_name)>64
      OR p_name !~ '^[a-z][a-z0-9_]*(:[a-z][a-z0-9_]*)?$' THEN RAISE EXCEPTION 'Nama permission tidak valid'; END IF;
    INSERT INTO public.permissions(name,description) VALUES(p_name,p_description) RETURNING id INTO result;
  END IF;
  RETURN result;
END $$;

REVOKE INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER,REFERENCES ON public.roles,public.permissions,public.role_permissions,public.admin_roles FROM PUBLIC,anon,authenticated;
DO $$ DECLARE f regprocedure;
BEGIN
  FOREACH f IN ARRAY ARRAY['public.admin_save_role(bigint,text,text,bigint[])'::regprocedure,
    'public.admin_delete_role(bigint)'::regprocedure,'public.admin_set_membership(uuid,bigint,boolean)'::regprocedure,
    'public.admin_save_permission(bigint,text,text,boolean)'::regprocedure] LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',f);
  END LOOP;
END $$;

-- Source: 011_admin_action_guards.sql
-- SHA256: 9a95ec8baa8b68949387fe0a0d50935a4cc26a1dbe548d317d57b3db052adfaf
CREATE OR REPLACE FUNCTION public.enforce_admin_domain_permission()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE needed text:=TG_ARGV[0]; feature_name text;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF TG_TABLE_NAME='user_feature_blacklist' THEN
      IF TG_OP='UPDATE' AND (NEW.feature IS DISTINCT FROM OLD.feature OR NEW.user_id IS DISTINCT FROM OLD.user_id
        OR NEW.alumni_id IS DISTINCT FROM OLD.alumni_id OR NEW.blacklisted_by IS DISTINCT FROM OLD.blacklisted_by) THEN
        RAISE EXCEPTION 'Identitas pemblokiran tidak dapat dipindahkan. Buat catatan baru untuk koreksi.';
      END IF;
      IF TG_OP='DELETE' THEN feature_name:=OLD.feature::text; ELSE feature_name:=NEW.feature::text; END IF;
      needed:=CASE feature_name WHEN 'alumni' THEN 'manage_users' WHEN 'berita' THEN 'manage_berita'
        WHEN 'kegiatan' THEN 'manage_kegiatan' WHEN 'komunitas' THEN 'manage_komunitas'
        WHEN 'donasi' THEN 'manage_donasi' ELSE 'moderate_content' END;
    END IF;
    IF (TG_TABLE_NAME IN ('alumni_verification','komunitas_verification','kegiatan_verification','donasi_verification','user_feature_blacklist')
      OR EXISTS(SELECT 1 FROM public.admin_roles WHERE user_id=auth.uid()))
      AND NOT public.app_admin_allowed(needed) THEN
      RAISE EXCEPTION 'Tidak memiliki izin untuk tindakan ini' USING ERRCODE='42501';
    END IF;
    IF TG_OP='INSERT' AND TG_TABLE_NAME IN ('alumni_verification','komunitas_verification','kegiatan_verification','donasi_verification') THEN
      NEW.verificator_id:=auth.uid();
    ELSIF TG_OP='INSERT' AND TG_TABLE_NAME='user_feature_blacklist' THEN
      NEW.blacklisted_by:=auth.uid();
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.enforce_admin_domain_permission() FROM PUBLIC,anon,authenticated;

DO $$ DECLARE row record;
BEGIN
  FOR row IN SELECT * FROM (VALUES
    ('berita','manage_berita'),('kegiatan','manage_kegiatan'),('tantangan','manage_kegiatan'),
    ('komunitas','manage_komunitas'),('donasi','manage_donasi'),('messages','moderate_content'),
    ('alumni_verification','manage_users'),('komunitas_verification','manage_komunitas'),
    ('kegiatan_verification','manage_kegiatan'),('donasi_verification','manage_donasi'),
    ('user_feature_blacklist','moderate_content')
  ) mapping(table_name,permission_name) LOOP
    EXECUTE format('CREATE TRIGGER app_admin_domain_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.enforce_admin_domain_permission(%L)',row.table_name,row.permission_name);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.admin_verify_entity(p_entity text,p_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE needed text; parent uuid; verification_id text;
BEGIN
  needed:=CASE p_entity WHEN 'alumni' THEN 'manage_users' WHEN 'berita' THEN NULL
    WHEN 'kegiatan' THEN 'manage_kegiatan' WHEN 'komunitas' THEN 'manage_komunitas' WHEN 'donasi' THEN 'manage_donasi' END;
  IF needed IS NULL OR NOT public.app_admin_allowed(needed) THEN RAISE EXCEPTION 'Tidak memiliki izin melakukan verifikasi' USING ERRCODE='42501'; END IF;
  EXECUTE format('SELECT id FROM public.%I WHERE id=$1 %s FOR UPDATE',p_entity,
    CASE WHEN p_entity='alumni' THEN '' ELSE 'AND archived_at IS NULL' END) INTO parent USING p_id;
  IF parent IS NULL THEN RAISE EXCEPTION 'Data tidak ditemukan atau sudah diarsipkan'; END IF;
  EXECUTE format('SELECT id::text FROM public.%I WHERE %I=$1 ORDER BY created_at,id LIMIT 1',p_entity||'_verification',p_entity||'_id') INTO verification_id USING p_id;
  IF verification_id IS NOT NULL THEN RETURN jsonb_build_object('id',verification_id,'already_verified',true); END IF;
  EXECUTE format('INSERT INTO public.%I(%I,verificator_id) VALUES($1,$2) RETURNING id::text',p_entity||'_verification',p_entity||'_id') INTO verification_id USING p_id,auth.uid();
  RETURN jsonb_build_object('id',verification_id,'already_verified',false);
END $$;
REVOKE ALL ON FUNCTION public.admin_verify_entity(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_verify_entity(text,uuid) TO authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.alumni_verification,public.komunitas_verification,public.kegiatan_verification,public.donasi_verification FROM PUBLIC,anon,authenticated;


-- Source: 012_account_review.sql
-- SHA256: 4009596d9530bd67d6da02355f3b7152431d440bce7045bce2aa7eb58a1d9031
CREATE OR REPLACE FUNCTION public.admin_request_account_review(p_alumni_id uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE owner_id uuid; result uuid;
BEGIN
  IF NOT public.app_admin_allowed('manage_users') THEN RAISE EXCEPTION 'Tidak memiliki izin meninjau akun' USING ERRCODE='42501'; END IF;
  SELECT user_id INTO owner_id FROM public.alumni WHERE id=p_alumni_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Profil tidak ditemukan'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(owner_id::text,0));
  SELECT id INTO result FROM public.account_deletion_requests WHERE user_id=owner_id AND status IN ('pending','approved','processing') ORDER BY requested_at DESC LIMIT 1;
  IF result IS NULL THEN
    INSERT INTO public.account_deletion_requests(user_id,status,reason,metadata)
    VALUES(owner_id,'pending','Peninjauan penghapusan diajukan melalui dashboard admin.',jsonb_build_object('source','admin','requested_by',auth.uid())) RETURNING id INTO result;
  END IF;
  RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.admin_review_account_request(p_id uuid,p_status text,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result uuid;
BEGIN
  IF NOT public.app_admin_allowed('manage_users') THEN RAISE EXCEPTION 'Tidak memiliki izin meninjau akun' USING ERRCODE='42501'; END IF;
  IF p_status IS NULL OR p_status NOT IN ('approved','rejected') OR nullif(btrim(p_reason),'') IS NULL OR length(p_reason)>2000 THEN RAISE EXCEPTION 'Keputusan dan alasan peninjauan wajib diisi'; END IF;
  UPDATE public.account_deletion_requests SET status=p_status,processed_by=auth.uid(),processed_at=now(),updated_at=now(),
    metadata=jsonb_set(CASE WHEN jsonb_typeof(metadata)='object' THEN metadata ELSE '{}'::jsonb END,'{review_reason}',to_jsonb(btrim(p_reason)),true)
    WHERE id=p_id AND status='pending' RETURNING id INTO result;
  IF result IS NULL THEN RAISE EXCEPTION 'Permintaan tidak ditemukan atau sudah diproses'; END IF;
  RETURN result;
END $$;

CREATE POLICY app_account_review_admin_read ON public.account_deletion_requests FOR SELECT TO authenticated USING(public.app_admin_allowed('manage_users'));
GRANT SELECT ON public.account_deletion_requests TO authenticated;
REVOKE UPDATE,DELETE ON public.account_deletion_requests FROM PUBLIC,anon,authenticated;
REVOKE DELETE ON public.alumni,public.alumni_private FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_request_account_review(uuid),public.admin_review_account_request(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_request_account_review(uuid),public.admin_review_account_request(uuid,text,text) TO authenticated;

COMMIT;
